// save access token after login
const res = pm.response.json();
if (res.data && res.data.accessToken) {
    pm.collectionVariables.set("accessToken", res.data.accessToken);
}

// save first stock (warehouse + item) that has available quantity
const res = pm.response.json();
const stock = (res.data || []).find(s => s.availableQuantity > 0);
if (stock) {
    pm.collectionVariables.set("fromWarehouseId", stock.warehouseId._id);
    pm.collectionVariables.set("itemId", stock.itemId._id);
}

pm.test('Status is 201', () => pm.response.to.have.status(201));
const d = pm.response.json().data;
if (d && d._id) { pm.collectionVariables.set('transferId', d._id); console.log('transferId saved:', d._id); }
